def rle(s: str) -> str:
    if not s:
        return ''
    res = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append(f"{prev}{count}")
            prev = ch
            count = 1
    res.append(f"{prev}{count}")
    return ''.join(res)
```

